(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18+Math.cos(y*0.013-t*0.22)*12+Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.019-t*0.24)*18+Math.sin(x*0.016+t*0.33)*12+Math.cos((x-y)*0.009-t*0.18)*8;
  const w2x = Math.sin(y*0.011+t*0.4)*6+Math.cos(x*0.022-t*0.15)*5;
  const w2y = Math.cos(x*0.012-t*0.35)*6+Math.sin(y*0.02+t*0.2)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.5)*110, 160+Math.sin(t*0.7)*55, 0.095, 1.8, 0.9],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.5+1)*95, 0.058, 2.4, 1.1],
    [120+Math.cos(t*0.8+1)*90, 180+Math.sin(t*0.6+3)*65, 0.11, 1.6, 0.85],
    [360+Math.sin(t*0.4+4)*100, 60+Math.cos(t*0.9+2)*75, 0.068, 2.7, 1.05],
    [240+Math.cos(t*0.35+5)*130, 200+Math.sin(t*0.55)*85, 0.085, 2.0, 0.95],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.75+1)*50, 0.13, 1.4, 0.8],
    [400+Math.cos(t*0.45+2)*80, 220+Math.sin(t*0.85+4)*60, 0.072, 2.5, 1.15]
  ];
  let aS=0, iS=0, wS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    wS+=Math.sin(d*f*0.4-t*sp*0.8+3.1)*w*0.5;
  }
  const tw=8, act=aS/tw, inh=iS/tw, wav=wS/tw;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2;
  const bg2=(Math.sin((sx+sy)*0.11+t*2.3)+Math.sin((sx-sy)*0.095-t*1.8))*0.22;
  const bg3=Math.sin(sx*0.07+t*1.5)*Math.sin(sy*0.065-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1))*0.35;
  const sp2=Math.sin(dist*0.08-ang*2+t*2.2)*0.15;
  const sp3=Math.cos(dist*0.02+ang*6-t*0.8)*0.1;
  const spiral=sp1+sp2+sp3;
  const rd1=Math.tanh((act-inh*0.65+bg*0.25+spiral)*2.0);
  const rd2=Math.tanh((act*0.8-inh*0.8+wav*0.4+bg2*0.3+sp2*0.5)*2.5);
  const rd3=Math.tanh((inh*0.5-act*0.3+bg3*0.6+sp3*2.0)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.45)*1.6)*0.25;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.28-t*2.5)*0.06;
  const blend=rd1*0.45+rd2*0.25+rd3*0.1+cell*0.15+micro;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,42,88],[18,78,118],[28,125,135],[65,158,125],[140,178,95],[198,185,72],[218,155,65],[210,115,72],[185,72,72],[140,45,72],[95,28,62],[55,18,55],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const intensity=Math.abs(rd1)+Math.abs(rd2)*0.5;
  const lum=0.75+Math.tanh(intensity*Math.PI*0.8)*0.25;
  const glow=Math.max(0, intensity-0.6)*0.8;
  const edge=Math.abs(rd1)>0.65||Math.abs(rd2)>0.7?1.12:1.0;
  const shimmer=Math.sin(ang*5+dist*0.06-t*3)*0.04*glow;
  return [
    Math.min(255,Math.max(0,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40+shimmer*80))|0),
    Math.min(255,Math.max(0,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30+shimmer*60))|0),
    Math.min(255,Math.max(0,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50+shimmer*100))|0)
  ];
}
